<script lang="ts">import { enhance } from '$app/forms'; let { data, form } = $props();</script>
<p class="eyebrow">Room notifications</p><h1>Keep the room in the loop.</h1>
<section class="card"><div class="section-heading"><h2>Slack</h2><span class="badge">{data.configured ? 'Webhook configured' : 'Setup needed'}</span></div><p class="muted">Expenses, payments, rejected shares, spam reports, review votes, verdicts, penalties and join requests are sent to your Slack channel. Incoming messages are not read.</p><p>{data.status.pending} queued · {data.status.failed ?? 0} awaiting retry</p><p class="muted">Failed deliveries remain saved and retry when the app is used. You can also request a retry below. A connection timeout can occasionally cause a duplicate message.</p>{#if form?.message}<p class="error" role="alert">{form.message}</p>{/if}{#if form?.success}<p class="success" role="status">{form.success}</p>{/if}{#if data.canSetWebhook}<form method="POST" action="?/configure" class="webhook-form"><label for="webhook">Incoming Webhook URL for this room</label><input id="webhook" name="webhook" type="url" required autocomplete="off" placeholder="https://hooks.slack.com/services/..." /><p class="muted">Saved only for this room. Use a separate Slack channel to keep room messages separate.</p><button class="secondary">Save webhook</button></form>{/if}<div class="button-row"><form method="POST" action="?/test" use:enhance><button class="button" disabled={!data.configured}>Send test message</button></form><form method="POST" action="?/retry" use:enhance><button class="secondary" disabled={!data.configured}>Retry queued messages</button></form></div></section>
<section class="card"><h2>Recent deliveries</h2>{#each data.recent as message}<article class="delivery"><span class="badge">{message.sentAt ? 'Sent' : message.lastError ?? 'Queued'}</span><p>{message.message}</p></article>{:else}<p class="muted">Room activity will appear here.</p>{/each}</section>
<style>.card{margin-bottom:20px}.webhook-form{margin-bottom:20px}.delivery{padding:16px 0;border-top:1px solid #e1e8e2}.delivery p{overflow-wrap:anywhere}</style>
